query:
# Successful txs signed by $caller at or above $minHeight that emitted a
# ProposalCreated event from gno.land/r/gov/dao. Returns the message content
# (MsgRun package body or MsgCall args) so a caller can match the tx to the
# proposal it intended to create (e.g. katana recovering the id of an
# `unconfirmed` broadcast whose gnokey output carried no TX HASH).
#
# Verified against the gnoland-test devnet tx-indexer
# (ghcr.io/gnolang/tx-indexer@sha256:174d52f2...) on 2026-10-12.
# FilterInt has only eq/gt/lt (no gte): pass minHeight-1 as $afterHeight.
query proposalsByCaller($caller: String!, $afterHeight: Int!) {
  getTransactions(
    where: {
      success: { eq: true }
      block_height: { gt: $afterHeight }
      messages: {
        value: {
          _or: [
            { MsgRun: { caller: { eq: $caller } } }
            { MsgCall: { caller: { eq: $caller } } }
          ]
        }
      }
      response: {
        events: {
          GnoEvent: {
            type: { eq: "ProposalCreated" }
            pkg_path: { eq: "gno.land/r/gov/dao" }
          }
        }
      }
    }
  ) {
    hash
    block_height
    index
    messages {
      typeUrl
      route
      value {
        ... on MsgRun {
          caller
          package {
            name
            path
            files {
              name
              body
            }
          }
        }
        ... on MsgCall {
          caller
          pkg_path
          func
          args
        }
      }
    }
    response {
      events {
        ... on GnoEvent {
          type
          pkg_path
          attrs {
            key
            value
          }
        }
      }
    }
  }
}
